import { ChangeDetectionStrategy, Component, computed, input, model, signal } from '@angular/core';
export interface AevkoComboboxItem {
  value: string;
  label: string;
  disabled?: boolean;
  keywords?: readonly string[];
}
@Component({
  selector: 'aevko-combobox',
  standalone: true,
  templateUrl: './combobox.component.html',
  styleUrl: './combobox.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AevkoCombobox {
  readonly label = input.required<string>();
  readonly placeholder = input('Search options…');
  readonly emptyMessage = input('No items found.');
  readonly items = input.required<readonly AevkoComboboxItem[]>();
  readonly value = model('');
  readonly query = model('');
  protected readonly open = signal(false);
  protected readonly active = signal(0);
  protected readonly filtered = computed(() => {
    const q = this.query().trim().toLocaleLowerCase();
    return this.items().filter(
      (item) =>
        !q || [item.label, ...(item.keywords ?? [])].join(' ').toLocaleLowerCase().includes(q),
    );
  });
  protected inputValue(value: string): void {
    this.query.set(value);
    this.open.set(true);
    this.active.set(0);
  }
  protected keydown(event: KeyboardEvent): void {
    const items = this.filtered().filter((item) => !item.disabled);
    if (event.key === 'Escape') {
      this.open.set(false);
      return;
    }
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault();
      this.open.set(true);
      this.active.update(
        (i) => (i + (event.key === 'ArrowUp' ? -1 : 1) + items.length) % items.length,
      );
    } else if (event.key === 'Enter') {
      event.preventDefault();
      const item = items[this.active()];
      if (item) this.choose(item);
    }
  }
  protected choose(item: AevkoComboboxItem): void {
    if (!item.disabled) {
      this.value.set(item.value);
      this.query.set(item.label);
      this.open.set(false);
    }
  }
}

:host {
  display: inline-block;
  min-inline-size: 14rem;
  position: relative;
}
input {
  background: var(--aevko-surface, #fff);
  border: 1px solid var(--aevko-border, #a3a3a3);
  border-radius: 0;
  color: inherit;
  inline-size: 100%;
  min-block-size: 2.5rem;
  padding: 0.5rem 0.75rem;
}
input:focus-visible {
  outline: 2px solid var(--aevko-ring, #a3a3a3);
  outline-offset: 2px;
}
[role='listbox'] {
  background: var(--aevko-surface, #fff);
  border: 1px solid var(--aevko-border, #d4d4d4);
  box-shadow: 0 12px 30px rgb(0 0 0 / 0.12);
  inline-size: 100%;
  inset-block-start: calc(100% + 0.25rem);
  max-block-size: 16rem;
  overflow: auto;
  padding: 0.25rem;
  position: absolute;
  z-index: 35;
}
[role='option'] {
  padding: 0.625rem;
}
[role='option']:hover,
[role='option'][data-active='true'] {
  background: var(--aevko-muted, #eee);
}
[role='option'][aria-disabled='true'] {
  opacity: 0.45;
}
p {
  color: var(--aevko-muted-foreground, #666);
  padding: 0.75rem;
}
@media (prefers-color-scheme: dark) {
  :host {
    --aevko-surface: #171717;
    --aevko-border: #404040;
    --aevko-muted: #2a2a2a;
    color: #f5f5f5;
  }
}
